{"code": "export async function main(input: { project: string }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const out: { shortId: string; owner: string }[] = [];
  for (const issue of targets) {
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    out.push({ shortId: issue.shortId, owner: blame.authorEmail });
  }
  return { total: issues.length, unresolved: targets.map(i => ({ shortId: i.shortId, filename: i.filename, line: i.lineNumber, count: i.count })), out };
